import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)
def pkgs(d):
    r = {}
    for p in d['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                r[(name, pkg['id'])] = pkg['resolvedVersion']
    return r
bp, ap = pkgs(b), pkgs(a)
print('All match:', bp == ap)
for k in sorted(set(list(bp.keys()) + list(ap.keys()))):
    bv, av = bp.get(k,'MISSING'), ap.get(k,'MISSING')
    status = 'OK' if bv == av else 'CHANGED'
    print(f'  {k[0]:12s} {k[1]:50s} {bv:8s} -> {av:8s}  {status}')
"

